import{_ as t,o,c as r,ag as a}from"./chunks/framework.D7xI0JV8.js";const m=JSON.parse('{"title":"zkML Models: Privacy-Preserving AI","description":"","frontmatter":{},"headers":[],"relativePath":"zkml-models.md","filePath":"zkml-models.md"}'),i={name:"zkml-models.md"};function n(s,e,d,l,c,p){return o(),r("div",null,[...e[0]||(e[0]=[a(`<h1 id="zkml-models-privacy-preserving-ai" tabindex="-1">zkML Models: Privacy-Preserving AI <a class="header-anchor" href="#zkml-models-privacy-preserving-ai" aria-label="Permalink to &quot;zkML Models: Privacy-Preserving AI&quot;">​</a></h1><p>zkde.fi uses <strong>zero-knowledge machine learning (zkML)</strong> to run AI inference <strong>on your private data</strong> while generating cryptographic proofs of correctness. Your portfolio positions, risk tolerance, and strategy preferences <strong>never leave your control</strong>, yet you still get proven AI recommendations.</p><h2 id="the-privacy-problem-with-traditional-ai" tabindex="-1">The Privacy Problem with Traditional AI <a class="header-anchor" href="#the-privacy-problem-with-traditional-ai" aria-label="Permalink to &quot;The Privacy Problem with Traditional AI&quot;">​</a></h2><p>When AI says &quot;this pool is safe for you&quot; or &quot;your risk grade is high,&quot; you face a dilemma:</p><p><strong>Centralized AI:</strong> Send your private data to a server, trust they run the right model, no verification <strong>On-chain AI:</strong> Publish your data publicly for transparency, expose everything to MEV bots and competitors</p><p>Neither option gives you <strong>privacy + verification</strong>.</p><h2 id="why-privacy-preserving-zkml-matters" tabindex="-1">Why Privacy-Preserving zkML Matters <a class="header-anchor" href="#why-privacy-preserving-zkml-matters" aria-label="Permalink to &quot;Why Privacy-Preserving zkML Matters&quot;">​</a></h2><p>zkML <strong>proves the AI model ran correctly WITHOUT revealing your inputs</strong>. The computation oracle pattern means:</p><ul><li><strong>Privacy-preserving risk scoring:</strong> AI analyzes your hidden positions, outputs a proven risk score</li><li><strong>Confidential anomaly detection:</strong> Models check pool health without exposing your stake</li><li><strong>Private strategy recommendations:</strong> Personalized suggestions based on your secret risk profile</li></ul><p>Smart contracts verify proofs on-chain. You get AI-powered decisions with <strong>mathematical privacy guarantees</strong>.</p><h2 id="core-endpoints" tabindex="-1">Core Endpoints <a class="header-anchor" href="#core-endpoints" aria-label="Permalink to &quot;Core Endpoints&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Endpoint</th><th>Purpose</th></tr></thead><tbody><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/zkml/risk_score</code></td><td>Risk score proof/signal generation</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/zkml/anomaly</code></td><td>Anomaly signal generation</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/zkml/combined</code></td><td>Combined risk + anomaly path</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/zkdefi/zkml/status</code></td><td>zkML subsystem status</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/zkdefi/zkml/pool-safety</code></td><td>Pool safety snapshot</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/zkml/scan</code></td><td>Scan-oriented model path</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/zkdefi/zkml/circuits</code></td><td>Circuit metadata</td></tr></tbody></table><h2 id="model-usage-context" tabindex="-1">Model Usage Context <a class="header-anchor" href="#model-usage-context" aria-label="Permalink to &quot;Model Usage Context&quot;">​</a></h2><pre class="mermaid" data-mermaid-source="flowchart%20LR%0A%20%20I%5BIntent%5D%20--%3E%20M%5BzkML%20endpoints%5D%0A%20%20M%20--%3E%20G%5BPolicy%2Fgate%20decision%20context%5D%0A%20%20G%20--%3E%20E%5BExecution%20path%5D%0A%20%20E%20--%3E%20R%5BReceipts%20and%20timeline%5D">flowchart LR
  I[Intent] --&gt; M[zkML endpoints]
  M --&gt; G[Policy/gate decision context]
  G --&gt; E[Execution path]
  E --&gt; R[Receipts and timeline]</pre><h2 id="problem-it-solves-in-execution" tabindex="-1">Problem It Solves In Execution <a class="header-anchor" href="#problem-it-solves-in-execution" aria-label="Permalink to &quot;Problem It Solves In Execution&quot;">​</a></h2><p>Model outputs create structured risk signals before execution, reducing blind automation behavior.</p><h2 id="why-it-matters-for-integrators" tabindex="-1">Why It Matters For Integrators <a class="header-anchor" href="#why-it-matters-for-integrators" aria-label="Permalink to &quot;Why It Matters For Integrators&quot;">​</a></h2><p>Teams can build explicit branching logic from structured outcomes instead of hardcoding opaque strategy assumptions.</p><h2 id="production-vs-experimental-note" tabindex="-1">Production Vs Experimental Note <a class="header-anchor" href="#production-vs-experimental-note" aria-label="Permalink to &quot;Production Vs Experimental Note&quot;">​</a></h2><p>Model APIs are active but may evolve quickly in payload detail across releases. Integrators should parse defensively and pin client behavior to tested API versions.</p><p>Next: <a href="/docs/rebalancing.html">Rebalancing</a> | <a href="/docs/api-overview.html">API overview</a> | <a href="/docs/developers.html">Developers</a></p>`,21)])])}const u=t(i,[["render",n]]);export{m as __pageData,u as default};
